def link_existing_assessments(apps, schema_editor):
    Application = apps.get_model('admin_api', 'AdoptionApplication')
    Assessment = apps.get_model('admin_api', 'RemoteAssessment')
    alias = schema_editor.connection.alias
    for application in Application.objects.using(alias).iterator():
        items = list(Assessment.objects.using(alias).filter(appId=str(application.pk)).order_by('date', 'time', 'created_at'))
        assigned = set()
        for item in items:
            # Prefer explicit persisted links. Keep additional historic rows,
            # without allowing them to occupy a new canonical appointment slot.
            if application.assessment_2_link and item.link == application.assessment_2_link:
                phase = 'post_adoption'
            elif application.assessment_1_link and item.link == application.assessment_1_link:
                phase = 'first'
            else:
                phase = 'first' if 'first' not in assigned else 'post_adoption'
            if phase in assigned:
                phase = 'legacy'
            assigned.add(phase)
            item.application_id = application.pk
            item.phase = phase
            item.save(using=alias, update_fields=['application', 'phase'])


